<?php
use Dilemma\Views;
use Dilemma\I18n;
use Dilemma\Support;
$member = $debate['viewer_member'];
$id = $debate['id'];
$participants = array_column($debate['participants'], null, 'user_id');
$active = in_array($debate['status'], ['active', 'paused'], true);
$turn = null;
foreach ($participants as $participant) if ((int) $participant['side'] === (int) $debate['turn_side']) $turn = $participant;
$action_form = static function (string $action, string $label, string $class = 'secondary', string $confirm = '') use ($id, $debate): string {
	return Views::form('/api/debates/' . $id . '/action', $action === 'flag' ? 'flag' : 'reload', $confirm !== '' ? 'data-confirm="' . $confirm . '"' : '') . Views::hidden('revision', $debate['revision']) . Views::hidden('action', $action) . Views::submit($label, $class) . '</form>';
};
?>
<article class="debate-page" data-debate="<?= $e($id) ?>">
<header class="debate-heading"><div class="debate-heading-meta"><a href="/explore?topic=<?= rawurlencode($debate['topic']) ?>"><?= $e($debate['topic']) ?></a><span class="status status-<?= $e($debate['status']) ?>"><?= $t($debate['status'] === 'open' ? 'looking_for_opponent' : $debate['status']) ?></span><span><?= $t($debate['is_public'] ? 'public' : 'private') ?></span></div><h1><?= $e($debate['title']) ?></h1><?php if ($debate['thesis'] !== $debate['title']): ?><p class="thesis user-text"><?= $e($debate['thesis']) ?></p><?php endif; ?><?php if ($debate['introduction'] !== ''): ?><p class="user-text introduction"><?= $e($debate['introduction']) ?></p><?php endif; ?><?php if ($debate['hidden']): ?><p class="notice"><?= $t('hidden') ?></p><?php endif; ?></header>
<div class="stance-pair"><?php foreach ($participants as $participant): ?><section class="stance side-<?= (int) $participant['side'] ?>"><div class="participant-mark" aria-hidden="true"><?= (int) $participant['side'] === 0 ? 'A' : 'B' ?></div><div><?= Views::avatar($participant['avatar']) ?><h2><?php if ($participant['account_status'] !== 'deleted'): ?><a href="/profile/<?= $e($participant['user_id']) ?>"><?= $e($participant['alias']) ?></a><?php else: ?><?= $t('deleted_participant') ?><?php endif; ?></h2><p class="user-text"><?= $e($participant['stance']) ?></p></div></section><?php endforeach; ?></div>
<?php if ($debate['flag_user_id']): ?><section class="flag-result"><span class="mini-flag" aria-hidden="true"></span><div><h2><?= $t('flag_title') ?></h2><p><?= $e($participants[$debate['flag_user_id']]['alias'] ?? '') ?></p></div><button class="button secondary" type="button" data-replay-flag><?= $t('replay_flag') ?></button></section><?php elseif ($debate['end_reason'] && !$debate['end_proposed_by']): ?><p class="notice"><?= $t($debate['end_reason']) ?></p><?php endif; ?>
<?= Views::render('sharing', compact('member', 'debate', 'id')) ?>
<?php if ($active && $turn): ?><div class="turn-indicator"><span class="turn-dot side-<?= (int) $turn['side'] ?>" aria-hidden="true"></span><p><?= $member && $turn['user_id'] === $user['id'] ? $t('your_turn') : $t('waiting_turn') . ' ' . $e($turn['alias']) ?></p></div><?php endif; ?>
<?php if ($member): ?><?= Views::render('debate-ai', compact('debate', 'user', 'actor')) ?><?php endif; ?>
<?php if ($member): ?><?= Views::render('pwa', []) ?><?php endif; ?>
<?php if (!in_array($debate['status'], ['draft', 'invited', 'open'], true)): ?>
<section class="argument-section"><div class="section-heading"><h2><?= $t('arguments') ?></h2><span><?= (int) ceil((int) $debate['message_count'] / 2) ?> <?= $t('rounds') ?></span></div>
<?php if (!$debate['messages']): ?><p class="empty-message"><?= $t('no_arguments') ?></p><?php else: ?><div class="argument-timeline"><?php foreach ($debate['messages'] as $message): $author = $participants[$message['author_id']]; ?>
<details class="argument side-<?= (int) $author['side'] ?>" id="argument-<?= $e($message['id']) ?>" data-argument="<?= $e($message['id']) ?>"><summary><div class="argument-meta"><span class="argument-number"><?= (int) $message['ordinal'] ?></span><strong><?= $author['account_status'] === 'deleted' ? $t('deleted_participant') : $e($author['alias']) ?></strong><time datetime="<?= $e($message['created_at']) ?>Z"><?= $e(Views::date($message['created_at'])) ?></time></div><p class="argument-excerpt user-text"><?= $message['excerpt'] !== '' ? $e($message['excerpt']) . ((int) $message['body_length'] > 650 ? '…' : '') : $t('removed_content') ?></p><span class="expand-label"><?= $t('full_argument') ?> <span aria-hidden="true">+</span></span></summary><div class="argument-body" aria-live="polite"></div>
<?php if ($member && $message['author_id'] === $user['id'] && $debate['status'] !== 'archived'): ?><details class="amend-form"><summary><?= $t('clarification') ?></summary><?= Views::form('/api/arguments/' . $message['id'] . '/amend') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::area('clarification', 'clarification') ?><?= Views::area('sources_text', 'sources_input', '', false, 4000) ?><?= Views::submit('amend') ?></form></details><?php endif; ?></details>
<?php endforeach; ?></div><?= Views::pagination($debate['page'], $debate['pages']) ?><?php endif; ?></section>
<?php if ($member && $debate['status'] === 'active' && (int) $member['side'] === (int) $debate['turn_side'] && !$debate['hidden']): ?><section class="compose"><h2><?= $t('body') ?></h2><p><?= $t('manual_help') ?></p><?= Views::form('/api/debates/' . $id . '/argument', 'reload', 'data-draft="argument-' . $e($id) . '"') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::area('body', 'body', '', true, 20000) ?><label class="field"><span><?= $t('reply_to') ?></span><select name="reply_to_id"><option value=""><?= $t('no_reply') ?></option><?php foreach ($debate['messages'] as $message): ?><option value="<?= $e($message['id']) ?>">#<?= (int) $message['ordinal'] ?> · <?= $e(mb_substr($message['excerpt'], 0, 70)) ?></option><?php endforeach; ?></select></label><?= Views::area('sources_text', 'sources_input', '', false, 4000) ?><?= Views::submit('post') ?></form></section><?php endif; ?>
<section class="positions-panel" id="positions"><h2><?= $t('positions') ?></h2><p class="muted"><?= $t('positions_help') ?> <?= !$member ? $t('position_private_help') : '' ?></p>
<?php if (!$debate['positions']): ?><p><?= $t('no_positions') ?></p><?php else: ?><div class="position-chart"><div class="scale-labels"><span><?= $e($debate['left_label']) ?> · 0</span><span><?= $e($debate['right_label']) ?> · 100</span></div><?php foreach ($debate['positions'] as $position): $owner = $participants[$position['user_id']]; ?><div class="position-observation side-<?= (int) $owner['side'] ?>"><div><strong><?= $owner['account_status'] === 'deleted' ? $t('deleted_participant') : $e($owner['alias']) ?></strong><time><?= $e(Views::date($position['created_at'])) ?></time></div><meter min="0" max="100" value="<?= $position['value'] === null ? 0 : (int) $position['value'] ?>" <?= $position['value'] === null ? 'hidden' : '' ?> aria-label="<?= $e($owner['alias']) ?>"><?= (int) $position['value'] ?></meter><span><?= $position['value'] === null ? $t('not_given') : (int) $position['value'] ?></span><?php if ($position['note'] !== ''): ?><p class="user-text"><?= $e($position['note']) ?></p><?php endif; ?></div><?php endforeach; ?></div><?= Views::pagination($debate['position_page'], $debate['position_pages'], 'positions_page') ?><?php endif; ?></section>
<details class="history-panel" data-history="<?= $e($id) ?>"><summary><?= $t('history') ?></summary><label><span class="visually-hidden"><?= $t('all_events') ?></span><select data-event-filter><option value=""><?= $t('all_events') ?></option><?php foreach (['argument_published', 'agent_assessment', 'position_recorded', 'white_flag', 'paused', 'resumed'] as $kind): ?><option value="<?= $kind ?>"><?= $t($kind) ?></option><?php endforeach; ?></select></label><ol class="event-list"></ol><button type="button" class="button secondary" data-more-events><?= $t('load_more') ?></button><p class="form-feedback" role="status"></p></details>
<?php endif; ?>
<?php if ($member): ?><details class="participant-settings"><summary><?= $t('debate_settings') ?></summary>
<?php if ($active): ?><div class="human-actions"><?= $action_form($debate['status'] === 'paused' ? 'resume' : 'pause', $debate['status'] === 'paused' ? 'resume' : 'pause') ?><?= $action_form('stand', 'stand') ?><?= $action_form('flag', 'flag', '', 'flag_confirm') ?><?= $action_form('withdraw', 'stop_participating', 'secondary', 'stop_confirm') ?></div>
<?= Views::form('/api/debates/' . $id . '/action') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::hidden('action', 'position') ?><?= Views::scale($debate['left_label'], $debate['right_label']) ?><?= Views::submit('save_position') ?></form>
<div class="ending-panel"><?php if ($debate['end_proposed_by']): ?><p><?= $t('end_waiting') ?> <strong><?= $t($debate['end_reason']) ?></strong></p><?php if ($debate['end_proposed_by'] !== $user['id']) echo $action_form('accept_end', 'accept_end', '', 'end_confirm'); ?><?= $action_form('cancel_end', 'cancel_end') ?><?php else: ?><?= Views::form('/api/debates/' . $id . '/action') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::hidden('action', 'propose_end') ?><label class="field"><span><?= $t('propose_end') ?></span><select name="reason"><?php foreach (['agreement', 'partial_agreement', 'draw', 'disagreement'] as $reason): ?><option value="<?= $reason ?>"><?= $t($reason) ?></option><?php endforeach; ?></select></label><?= Views::submit('propose_end', 'secondary') ?></form><?php endif; ?></div>
<?php elseif (in_array($debate['status'], ['flagged', 'ended'], true)): ?><?= $action_form('archive', 'archive_action') ?><?php endif; ?>
<?= Views::form('/api/debates/' . $id . '/action') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::hidden('action', 'notifications') ?><?= Views::check('notify', 'notify_debate', (bool) $member['notify']) ?><?= Views::submit('save', 'secondary') ?></form>
<?= Views::form('/api/debates/' . $id . '/action') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::hidden('action', 'consent') ?><?= Views::consent($member) ?><?= Views::submit('save_consent') ?></form></details><?php endif; ?>
<?php if ($user): ?><details class="report-panel"><summary><?= $t('report') ?></summary><?= Views::form('/api/debates/' . $id . '/report', 'report') ?><?= Views::area('reason', 'reason', '', true, 2000) ?><?= Views::submit('send_report', 'secondary') ?></form></details><?php endif; ?>
</article>
<dialog id="flag-dialog" aria-labelledby="flag-title"><button class="dialog-close" type="button" data-close-dialog aria-label="<?= $t('close') ?>">×</button><div class="flag-scene" aria-hidden="true"><span class="mini-flag"></span></div><h2 id="flag-title"><?= $t('flag_title') ?></h2><p><?= $e($participants[$debate['flag_user_id']]['alias'] ?? $user['alias'] ?? '') ?></p><button type="button" class="button" data-close-dialog><?= $t('close') ?></button></dialog>
